tool_calls.arguments:
{"command":"kubectl patch deploy app --type=json -p '[
  {
    "op": "replace",
    "path": "/spec/template/spec/nodeSelector",
    "value": [
      {"node":"benchmark-antiaffinity-unschedulable-cd00cae0-control-plane"}
    ]
  },
  {
    "op": "remove",
    "path": "/spec/template/spec/maxUnavailable",
    "value": "maxUnavailable: none"
  }
]' 2>&1; sleep 3; kubectl get pods -l app 2>&1; echo "=== deployment status ==="; kubectl get deploy app 2>&1"}

